MAP
    NAME "SS_MAP_RURAL_LIBERACIONES_BRECHAS"
    INCLUDE  'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    #CONFIG "MS_ERRORFILE" "/srv/mapserver/brechas.txt"
    #DEBUG 5
    LAYER
        NAME "SS_MAP_RURAL_LIBERACIONES_BRECHAS"
        CONNECTIONTYPE POSTGIS
        INCLUDE 'includes/conexion.map'
        DATA "gm_liberaciones_brecha from l_liberaciones_brecha using unique id_elemento_geografico using srid=32614"
        STATUS DEFAULT
        TYPE POLYGON
        PROJECTION 
              "init=EPSG:32614"
        END #PROJECTION
        CLASS
            NAME "Liberaciones Brechas"
            LABEL	
                 TYPE TRUETYPE
                 FONT "arial"
                 SIZE 15
                 PARTIALS FALSE
                 COLOR 0 0 0
            END #LABEL 
            STYLE
                 OPACITY 75
                COLOR 10 102 10
            END #STYLE
            STYLE
                WIDTH 1
                OUTLINECOLOR 0 0 0
            END
        END #CLASS
    END #LAYER
END #MAP
